 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen0 = set()
    region = {}
    enclosed = set()
    # Connected 0-regions; only regions not reaching the canvas edge are enclosed.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r,c) in seen0:
                continue
            q = deque([(r,c)])
            seen0.add((r,c))
            cells = []
            edge = False
            while q:
                y,x = q.popleft()
                cells.append((y,x))
                if y == 0 or x == 0 or y == h-1 or x == w-1:
                    edge = True
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and (ny,nx) not in seen0:
                        seen0.add((ny,nx)); q.append((ny,nx))
            enclosed_flag = not edge
            for p in cells:
                region[p] = enclosed_flag
            if enclosed_flag:
                enclosed.add(tuple(cells))
    # Qualify each 4-connected 1 component only when it encloses a zero region.
    seen1=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r,c) in seen1:
                continue
            q=deque([(r,c)]); seen1.add((r,c)); comp=[]
            while q:
                y,x=q.popleft(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]==1 and (ny,nx) not in seen1:
                        seen1.add((ny,nx)); q.append((ny,nx))
            borders_hole = any(region.get((y+dy,x+dx),False)
                               for y,x in comp for dy,dx in ((1,0),(-1,0),(0,1),(0,-1))
                               if 0<=y+dy<h and 0<=x+dx<w)
            if not borders_hole:
                continue
            for y,x in comp:
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and grid[ny][nx]==0:
                            out[ny][nx] = 3 if region.get((ny,nx),False) else 2
    return out
